"""C1522 ting/tinct: a touch of color, a touch of emotion, and taint's merged histories."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
T=[['拉丁 tingere／tinctus','浸湿、染色／染过的，也有染色的名词形式']]
TI=T+[['英语旧形式 tinct；法语 teinte、意大利语 tinta 等相关形式','染色、色调；现代词形可能受到这些形式影响'],['英语 tint','色调、少许颜色；后也作染色动词']]
TG=T+[['英语 tinge〔动词〕','染上一点颜色；后来用于情感'],['英语 tinge〔名词〕','一点颜色或情绪']]
TA=[['两条来源：拉丁 tingere；另一支接触、达到的动词词族','一边是染色，一边经法律用法发展出定罪'],['古法语 teindre／teint；另有 ataindre／ataint／atteinte','染色、颜色；另一支为触及、指控、定罪及相关名词'],['中古英语染色词与 attaint 的缩短形式等汇合','染色、污点、耻辱的意义互相影响'],['现代英语 taint','污染、使名声受损；污染或污点的名词']]
W=[
E('tint','/tɪnt/','色调；少许颜色；给……染色','一张原本偏白的纸带一点暖黄，一片玻璃透出淡绿，这层颜色就可以叫 a tint。','接拉丁 tingere／tinctus 的染色词族。常分析为较早英语 tinct 的变形；法语 teinte、意大利语 tinta 等形式也被提出影响现代词形，所以不把它硬讲成从单一语言直接借来的唯一链。',TI,'日常 tint 可以是偏淡的一层颜色，也可说具体色调、染发剂。调色理论里还有更窄的用法：往某种颜色里加白得到的浅色是 a tint。这个专门定义不要反过来限制日常所有用法。','a green tint；a warm tint；tint the glass；tint someone’s hair。名词 tint 和动词 tint 同形同音。','tint、tinge 都能说少许颜色；tinge 更常引申为情绪中的一点成分。色彩术语里的 tint 常说加白，shade 常说加黑；普通谈颜色时，两词范围会更宽。',('The glass has a faint green tint.','这块玻璃带着淡淡的绿色。'),('She tinted the drawing with a little blue.','她给这幅画略略染上了一点蓝色。'),sources=['https://www.etymonline.com/word/tint','https://www.merriam-webster.com/dictionary/tint','https://www.oxfordlearnersdictionaries.com/definition/english/tint_1','https://en.wiktionary.org/wiki/tint']),
E('tinted','/ˈtɪntɪd/','着色的；染过颜色的','透明镜片加上一层颜色，头发染上不同色调，都能说 tinted：重点是颜色已经加上去了。','tint + -ed，是过去式、过去分词，也用作形容词。因为 tint 以 /t/ 结尾，-ed 读 /ɪd/，整个词有两个音节。',TI+[['tint + -ed → tinted','染过的、有颜色的；也表示过去做了染色动作']],'tinted windows 是有色玻璃窗；tinted lenses 是着色镜片。tinted 描述颜色处理，本身不保证某种具体防护性能。护肤品里的 tinted moisturizer 则是在保湿产品中带有一定颜色。','tinted glass；tinted lenses；tinted hair；tinted moisturizer。','tinted 不等于 painted“表面刷了油漆”。玻璃可以有整体色调而没有一层不透明的漆；也别与 tainted“被污染的”混淆，后者多了一个坏影响。',('The car has tinted rear windows.','这辆车的后窗装着有色玻璃。'),('She chose a tinted moisturizer for a little colour.','她选了一款带颜色的保湿产品，想添一点肤色效果。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/tinted','https://www.etymonline.com/word/tint']),
E('tinge','/tɪndʒ/','一点颜色；一丝情绪；使略带……','像把一滴颜色混进水里：整体还是原来的样子，却多了一点别的味道。声音里的遗憾、笑容里的苦涩也可以这样理解。','动词直接接拉丁 tingere“浸、染色”；英语名词从动词转用，记录较晚。它是完整借词，不拆成英语 tin“锡”加 -ge。',TG,'a tinge of sadness 是一丝悲伤，不是整个人完全沉进悲伤里。作动词时，可以说 regret tinged his voice：遗憾给声音染上了一点情绪颜色。这种比喻把看得见的染色变成听得出的情绪。','a tinge of pink；a tinge of regret；tinge something with something；be tinged with。','tinge 强调混入的少量颜色或情绪，通常不含道德评判；taint 多指坏成分或不良影响。a tinge of pride 可以只是有一点自豪。',('There was a tinge of regret in his reply.','他的回答里有一丝遗憾。'),('The evening light tinged the clouds with gold.','傍晚的光给云层染上了一点金色。'),sources=['https://www.etymonline.com/word/tinge','https://www.oxfordlearnersdictionaries.com/definition/english/tinge_1']),
E('tinged','/tɪndʒd/','略带某种颜色或感情的','喜悦里夹一点难过、白花边缘透一点粉，都可以说 tinged with：不是全部换色，而是掺入一丝。','tinge 的过去式、过去分词，词尾已有 e，只加 d；作为形容词表示已经略带某种成分。结尾 /dʒd/ 连读，不另加一个 /ɪd/ 音节。',TG+[['tinge → tinged','略微染上了；带着一丝某种感觉']],'Her relief was tinged with sadness 说她松了口气，却又有些难过。这种用法能同时保留两种感受，比只说 sad 更细。具体颜色也一样：tinged with pink 是透着一点粉。','tinged with sadness；tinged with irony；tinged with pink。常放在 be 后，也能作后置修饰，如 a voice tinged with doubt。','tinged 常提醒读者主要事物中掺入了少量另一种成分；tinted 更常描述有意着色的玻璃、头发或产品，但两者并不是绝对不能重叠。',('Her relief was tinged with sadness.','她松了一口气，但心里也夹着一丝难过。'),('The white petals were tinged with pink at the edges.','白色花瓣的边缘透着一点粉色。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/tinge_1','https://www.etymonline.com/word/tinge']),
E('tincture','英 /ˈtɪŋktʃə/；美 /ˈtɪŋktʃər/','酊剂；少许某种成分或意味〔较正式〕','先想一种东西浸入液体，把自己的成分带进液体里。这个旧染色词后来常用于含酒精的药用溶液。','来自拉丁 tinctura“染色”，接 tingere 的分词词干 tinct- 与动作名词结尾。英语先有染料、染色等用法，也很早进入药物语境；现代可辨 tinct- + -ure，但不是把英语 tint 原样加后缀。',T+[['拉丁 tinctura → 中古英语 tincture','染色、染料；亦用于药物材料'],['现代 tincture','常指酒精性药用溶液；也保留少许成分的比喻义']],'a tincture of iodine 指碘酊。herbal tincture 常是药材成分进入酒精或含水酒精后的液体制剂；名字说明制剂形式，不等于疗效结论。文学里 a tincture of irony 则借“掺进去一点”表示少许反讽意味。','a tincture of iodine；an herbal tincture；a tincture of humour。比喻义较正式，日常常用 a touch of 或 a tinge of。','tincture 不是所有液体药物的统称，通常与酒精性溶剂有关；tint 是颜色或染色，不能拿来直接替换“酊剂”。',('The museum displayed an old bottle labelled “tincture of iodine”.','博物馆展出了一只标着“碘酊”的旧瓶子。'),('A tincture of irony ran through her account of the ceremony.','她对仪式的叙述里带着一点反讽。'),sources=['https://www.etymonline.com/word/tincture','https://www.oxfordlearnersdictionaries.com/definition/english/tincture','https://en.wiktionary.org/wiki/tincture']),
E('taint','/teɪnt/','污染；玷污；污点；不良影响','清水混进坏成分，或一次成功蒙上作弊嫌疑：表面可能还像原来一样，人却开始觉得它不干净、不可信。','现代词由两条旧线汇合：一条经法语染色词接拉丁 tingere；另一条是 attaint“定罪”等法律词的缩短或相关形式。名词也有法语 teint“颜色”及 atteinte“指控、定罪”的旁支，不宜全画成现代动词派生。',TA,'taint the result 可以说坏因素损害了结果的可信度；a taint of corruption 是腐败的污点。它通常含负面判断，比 tinge 强得多。不过 taint 不只指道德，也能指食品、气味或物质受到污染。','taint a reputation；taint the evidence；a taint of corruption；be tainted by scandal。','tint 是染颜色，taint 是混入了有害或不光彩的影响。前者可以是装饰，后者往往意味着品质或信任受损；不能只当成两个不同发音的“染”。',('The cheating allegations tainted the team’s victory.','作弊指控让这支队伍的胜利蒙上了污点。'),('The investigation left a taint of suspicion around the deal.','这次调查让人们对这笔交易仍存疑虑。'),sources=['https://www.etymonline.com/word/taint','https://www.oxfordlearnersdictionaries.com/definition/english/taint_1']),
E('tainted','/ˈteɪntɪd/','受污染的；有污点的；受到不良影响的','给已经被坏成分影响的东西贴一个状态标签：食物不纯净了，证据不可靠了，名声不清白了。','taint + -ed，过去分词转作形容词；词尾 /t/ 后的 -ed 读 /ɪd/。taint 的染色与法律词两条来源仍在背后，不是从 tinted 改一个元音产生。',TA+[['taint + -ed → tainted','已经受到污染或坏影响的']],'tainted food 可以是受到有害物污染的食物；tainted evidence 可以是来源、取得过程或可靠性受不良因素影响的证据。它指出“掺进了问题”，并不自己说明究竟是哪一种问题。','tainted food；tainted water；a tainted reputation；evidence tainted by pressure。','tainted 是状态描述，taint 作动词说使它变坏的动作。tinted windows 是有色窗；tainted water 则不是水只是染了好看的颜色。',('The company recalled a batch of tainted food.','公司召回了一批受到污染的食品。'),('The review found that the evidence was tainted by conflicts of interest.','复核发现，利益冲突损害了这些证据的可信度。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/tainted','https://www.oxfordlearnersdictionaries.com/definition/english/taint_1','https://www.etymonline.com/word/taint']),
E('untainted','/ˌʌnˈteɪntɪd/','未受污染的；未沾污点的','周围出现了坏事，但某个人、某份材料或某种感情没有被那件事弄坏。它强调“没有受到这个污染”。','否定前缀 un- + tainted。早期已有人的道德清白义，后来也用于物质未受污染；不必把它讲成一定先有水，再有名声的单向比喻。',TA+[['tainted + 否定 un- → untainted','未受坏影响；未受污染']],'remain untainted by scandal 是在丑闻中仍未蒙上污点。untainted joy 可以是没有夹杂阴影的喜悦。这里的“纯净”要看具体对象，不是宣称一个人在所有方面都毫无缺点。','untainted by scandal；untainted evidence；remain untainted；untainted joy。','untainted 说没有受污染；clean 有时可以是清洗后的干净。untainted 这个词本身并不表示做过清洗、补救或洗刷名声。',('Her reputation remained untainted by the scandal.','她的声誉没有受到这场丑闻的损害。'),('The researchers kept an untainted sample for comparison.','研究人员留了一份未受污染的样本作比较。'),sources=['https://www.etymonline.com/word/untainted','https://www.oxfordlearnersdictionaries.com/definition/english/untainted']),
]
EX={w:'较专门的版画术语或较少用的旧式染色词，本轮优先常见颜色与抽象用法。' for w in ['aquatint','mezzotint','distain','tinct','tinctorial','tingent']}
ROOT=dict(id='C1522',meaning='浸湿；染色',core='tingere 的画面是浸进去、染上颜色。一点颜色能变成一丝情绪；若混入坏东西，又可以变成品质、名声的污点。',image='tingere 浸、染 → tinge 略染 → tinged；tinctus／tinct → tint → tinted；tinctura → tincture；染色与法律定罪两线汇合 → taint → tainted／untainted。',intro='这一族先抓住“原本的东西里多了一点成分”。颜色通常是中性的，情绪可以苦也可以甜；到了 taint，多半是混进坏影响，而且这个词还汇入了另一条法律词源。',forms='ting- 与 tinct- 是拉丁动词及分词词干的变化。tinge 是借入动词；tincture 借拉丁动作名词。tint 的词形演变存在不同分析，但染色词族的归属清楚。taint 是多条旧形式汇合，不能全归成 tint 的英语派生词。',branches=[['颜色和情绪的一点变化','tint, tinted, tinge, tinged'],['液体制剂与少许意味','tincture'],['污染与名声污点','taint, tainted, untainted']],contrasts='tinted 是着色，tinged 常是略带某种颜色或感情，tainted 则通常受到坏影响。记发音也能帮分开：/tɪnt/、/tɪndʒ/、/teɪnt/。',practice='把 a tint of blue 想成一点蓝，把 a tinge of sadness 想成一点难过，把 a taint of corruption 想成蒙上了一层腐败疑云。画面相近，但评价方向不相同。',words=[e['word'] for e in W],exclude=EX)
if __name__=='__main__':
 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id'])
 assert set(ROOT['words'])=={w for w in r['family'] if '-' not in w and w not in EX}
